def seed_decisions_watermark(apps, schema_editor):
    """Seed the decisions watermark to now.

    The table is re-created empty (0064 dropped the original), and
    ``SyncStatus.get_last_decisions_sync`` falls back to a 30-day-old
    default when no row exists — which would make the first daily
    incremental sync after rollout fetch a full 30-day window. Seeding
    the row keeps that first run to ~1 day.
    """
    from django.utils import timezone

    SyncStatus = apps.get_model("core", "SyncStatus")
    now = timezone.now()
    SyncStatus.objects.get_or_create(
        sync_type="decisions",
        defaults={
            "last_sync_timestamp": now,
            "last_sync_date": now.date(),
            "last_run_status": "completed",
        },
    )


